import{_ as o,o as t,c as i,a0 as a}from"./chunks/framework.DPd3ST4h.js";const h=JSON.parse('{"title":"Dogfood reviews","description":"How Redline reviews and publishes results on its own pull requests","frontmatter":{"title":"Dogfood reviews","description":"How Redline reviews and publishes results on its own pull requests"},"headers":[],"relativePath":"dogfood-review.md","filePath":"dogfood-review.md","lastUpdated":1792869603000}'),r={name:"dogfood-review.md"};function n(d,e,s,l,c,u){return t(),i("div",null,[...e[0]||(e[0]=[a('<h1 id="dogfood-reviews" tabindex="-1">Dogfood reviews <a class="header-anchor" href="#dogfood-reviews" aria-label="Permalink to &quot;Dogfood reviews&quot;">​</a></h1><p>Redline reviews its own pull requests through <code>.github/workflows/pr-review.yml</code>. That workflow calls <code>.github/workflows/dogfood-review.yml</code>, which runs the local <code>./github</code> action from the pull request&#39;s trusted base revision.</p><h2 id="trigger-and-trust-boundary" tabindex="-1">Trigger and trust boundary <a class="header-anchor" href="#trigger-and-trust-boundary" aria-label="Permalink to &quot;Trigger and trust boundary&quot;">​</a></h2><p>The wrapper runs on these <code>pull_request</code> events:</p><ul><li><code>opened</code>;</li><li><code>synchronize</code>;</li><li><code>reopened</code>;</li><li><code>edited</code>;</li><li><code>ready_for_review</code>.</li></ul><p>The workflow checks out the <code>github.event.pull_request.base.sha</code> revision before it calls <code>./github</code>. Pull request commits are fetched and processed as data. Redline does not install dependencies from the pull request, run its scripts, or execute its code.</p><p>This repository uses <code>pull_request</code> because its automatic reviews target same-repository branches, where the configured repository secrets are available. GitHub does not pass those secrets to an untrusted fork event. A fork event therefore takes the context-only path described below.</p><p>External repositories must use the <a href="/projects/redline/reusable-review-workflow">reusable review workflow</a>. Its caller uses <code>pull_request_target</code> so review and publication secrets are available while the action still treats pull request content only as data. Do not replace that caller with a pull request checkout or execute pull request code.</p><h2 id="review-enablement" tabindex="-1">Review enablement <a class="header-anchor" href="#review-enablement" aria-label="Permalink to &quot;Review enablement&quot;">​</a></h2><p>The caller maps the repository secret <code>MODEL_CREDENTIALS</code> to the reusable workflow&#39;s <code>model-auth</code> secret. The dogfood workflow sets all three review inputs together:</p><ul><li><code>backend</code>: <code>pi</code>;</li><li><code>model-config</code>: OpenRouter with <code>z-ai/glm-5.3-flash</code>;</li><li><code>model-auth</code>: the provider-keyed <code>MODEL_CREDENTIALS</code> value.</li></ul><p><code>backend</code> and <code>model-config</code> are non-empty only when <code>model-auth</code> is non-empty. This preserves the action&#39;s all-or-nothing review-input contract.</p><p>When <code>MODEL_CREDENTIALS</code> is absent, all three values are empty. The action builds and uploads the bounded context bundle but does not index source, install a harness, call a model, write review output, or publish review comments. A partial review-input set fails validation instead of silently degrading.</p><p>Configured dogfood reviews use <code>defects-and-risks</code> scope, action-owned indexing, four concurrent per-file calls, and the Node 24 TypeScript source runtime by default. The reusable dogfood inputs accept <code>review-concurrency</code> from 1 through 8 and <code>runtime</code> as <code>node</code> or <code>bun</code> (pinned to 1.4.4). The action installs the selected fixed harness package as trusted tooling. Pi runs with tools disabled, separate generated configuration and prompt files for every invocation, and only the selected model credential. Artifacts and publication stay in manifest order regardless of completion order.</p><h2 id="publication-credentials" tabindex="-1">Publication credentials <a class="header-anchor" href="#publication-credentials" aria-label="Permalink to &quot;Publication credentials&quot;">​</a></h2><p>The wrapper prefers the Redline GitHub App:</p><ul><li><code>REDLINE_REVIEW_APP_ID</code> supplies the App id;</li><li><code>REDLINE_REVIEW_PRIVATE_KEY</code> supplies the private key;</li><li>the action mints one installation token for the start/failure notification and a fresh token for final publication.</li></ul><p><code>GH_TOKEN</code> is the fallback publication credential. It is an owner-provided PAT, not the Actions <code>GITHUB_TOKEN</code>. The harness review step runs without either publication token.</p><p>With a publication credential, the action maintains one summary comment and publishes one GitHub review per file that has validated findings. Each finding becomes one bounded inline comment. Re-runs update the managed summary and skip an already published actor-owned review for the same head.</p><h2 id="artifacts" tabindex="-1">Artifacts <a class="header-anchor" href="#artifacts" aria-label="Permalink to &quot;Artifacts&quot;">​</a></h2><p>The artifact base name is:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>pull-request-review-&lt;pull-request-number&gt;-&lt;workflow-run-id&gt;</span></span></code></pre></div><p>Every run uploads <code>&lt;artifact-name&gt;-context</code>. It contains the context bundle, captured source at the reviewed head, and bounded provider-neutral indexed context when indexing completed.</p><p>A configured review also uploads <code>&lt;artifact-name&gt;-reviews</code>. It contains:</p><ul><li>one JSON and one Markdown record per reviewed file;</li><li><code>summary.json</code> and <code>summary.md</code> with run counts and per-file outcomes;</li><li><code>review.json</code> and <code>review.md</code> with synthesized findings, coverage, limitations, and the deterministic verdict.</li></ul><p>Configured dogfood reviews also use an automatic PR-scoped GitHub Actions cache for validated per-file <code>clean</code> and <code>findings</code> results. Unchanged semantic matches skip the model call; changed diffs, requirements, bounded source, or resolved indexed context execute again. The review artifact reports reused files, executed files, invalid cache entries ignored, and estimated model time saved.</p><p>The output is not the historical review journal. See <a href="/projects/redline/review-reporting">review output</a> for the current schemas and <a href="/projects/redline/github-composite-action">GitHub composite action</a> for the full pipeline.</p><h2 id="container-status" tabindex="-1">Container status <a class="header-anchor" href="#container-status" aria-label="Permalink to &quot;Container status&quot;">​</a></h2><p>The current action invokes Pi or OpenCode directly through the harness executor. It does not run the harness in Docker or Podman. <code>container-engine</code> remains a legacy reusable-workflow input for caller compatibility and is not forwarded to the action. Container sandboxing is a future milestone and must not be presented as implemented behavior.</p>',29)])])}const f=o(r,[["render",n]]);export{h as __pageData,f as default};
